<?php
require_once '../config/database.php';require_once '../includes/functions.php';
if(!admin()){go('login.php');}
$products=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();$users=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();$orders=(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();$revenue=(float)$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE status <> 'Cancelled'")->fetchColumn();$reviews=(int)$pdo->query('SELECT COUNT(*) FROM reviews')->fetchColumn();$cartRows=(int)$pdo->query('SELECT COUNT(*) FROM cart_items')->fetchColumn();$wishlistRows=(int)$pdo->query('SELECT COUNT(*) FROM wishlist_items')->fetchColumn();$recent=$pdo->query("SELECT o.id,u.name user_name,p.name product_name,o.quantity,o.total_amount,o.status,o.created_at FROM orders o JOIN users u ON u.id=o.user_id JOIN products p ON p.id=o.product_id ORDER BY o.id DESC LIMIT 8")->fetchAll();$pageTitle='Dashboard';$active='dashboard';require 'header.php';?><div class="admin-top"><div><span class="eyebrow">Rasit Watch</span><h1>Dashboard</h1><p>Manage your store from one secure admin area.</p></div><a class="btn secondary" href="../index.php">View Website ↗</a></div><div class="admin-stats"><div class="admin-stat"><span>Products</span><b><?=number_format($products)?></b><small>Store catalog</small></div><div class="admin-stat"><span>Customers</span><b><?=number_format($users)?></b><small>Registered users</small></div><div class="admin-stat"><span>Orders</span><b><?=number_format($orders)?></b><small>All orders</small></div><div class="admin-stat"><span>Revenue</span><b>₹<?=number_format($revenue,2)?></b><small>Non-cancelled orders</small></div></div><div class="admin-mini-grid"><div class="mini-card"><span>Reviews</span><b><?=$reviews?></b><a href="reviews.php">View reviews →</a></div><div class="mini-card"><span>Active Cart Items</span><b><?=$cartRows?></b><a href="cart.php">View cart data →</a></div><div class="mini-card"><span>Wishlist Items</span><b><?=$wishlistRows?></b><a href="wishlist.php">View wishlist data →</a></div></div><section class="admin-card"><div class="section-head"><div><h2>Recent Orders</h2><p>Latest store activity</p></div><a href="orders.php">View all →</a></div><div class="table-scroll"><table class="admin-table"><thead><tr><th>ID</th><th>Customer</th><th>Product</th><th>Qty</th><th>Total</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['user_name'])?></td><td><?=e($o['product_name'])?></td><td><?=$o['quantity']?></td><td>₹<?=number_format((float)$o['total_amount'],2)?></td><td><span class="status <?=strtolower($o['status'])?>"><?=e($o['status'])?></span></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;if(!$recent):?><tr><td colspan="7" class="empty-row">No orders yet.</td></tr><?php endif;?></tbody></table></div></section><?php require 'footer.php';
